contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, uint256 deadline) public payable {
        require(true);
        uint256 baseTargetBefore = c._BASE_TARGET_();
        uint256 quoteTargetBefore = c._QUOTE_TARGET_();
        require(c._RState_() == uint256(2)); // 2 is BELOW_ONE
        require(baseTargetBefore > c._BASE_RESERVE_());
        c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, hex"", deadline);
        uint256 baseTargetAfter = c._BASE_TARGET_();
        uint256 quoteTargetAfter = c._QUOTE_TARGET_();
        assert(baseTargetAfter * quoteTargetBefore == quoteTargetAfter * baseTargetBefore);
    }
}

